import hashlib
import math


class BloomFilter:
    """
    A simple Bloom Filter implementation to test for membership with a 
    specified false positive rate. This class uses basic hashing and 
    a bit array simulation to represent the filter's state.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.num_bits = self._optimal_size(expected_items, false_positive_rate)
        self.num_hashes = self._optimal_hash_count(self.num_bits, expected_items)
        self.bit_array = [0] * self.num_bits

    def _optimal_size(self, n: int, p: float) -> int:
        """Calculate the optimal bit array size."""
        return int(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((m / n) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Create a hash for the item with a given seed."""
        hash_object = hashlib.md5((str(seed) + item).encode()).hexdigest()
        return int(hash_object, 16) % self.num_bits

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.num_hashes):
            index = self._hash(item, i)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        for i in range(self.num_hashes):
            index = self._hash(item, i)
            if self.bit_array[index] == 0:
                return False
        return True

