class BloomFilter:
    """
    A Bloom Filter implementation that utilizes a list to represent the 
    bit array and employs multiple hash functions derived from the item 
    using a seed value. This design emphasizes a straightforward 
    approach to hashing and array management.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.size = self._calculate_size(expected_items, false_positive_rate)
        self.hash_count = self._calculate_hash_count(self.size, expected_items)
        self.bit_array = [False] * self.size

    def _calculate_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return int(-n * math.log(p) / (math.log(2) ** 2))

    def _calculate_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((m / n) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Compute a hash value for the item with a specific seed."""
        combined_input = (str(seed) + item).encode()
        hash_value = hashlib.sha256(combined_input).hexdigest()
        return int(hash_value, 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            self.bit_array[index] = True

    def contains(self, item: str) -> bool:
        """Check for the presence of an item in the Bloom Filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            if not self.bit_array[index]:
                return False
        return True

