class BloomFilter:
    """
    A Bloom Filter implementation that uses a simple caching mechanism
    for computed hashes and a fixed-size bit array to track membership
    of items. The algorithm calculates the size of the bit array and 
    the number of hash functions based on the expected items and 
    desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.num_bits = self._calculate_bit_array_size(expected_items, false_positive_rate)
        self.num_hashes = self._calculate_hash_count(self.num_bits, expected_items)
        self.bit_array = [False] * self.num_bits
        self.seeds = range(self.num_hashes)

    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the bit array size based on expected items and false positive rate."""
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def _calculate_hash_count(self, m: int, n: int) -> int:
        """Calculate the number of hash functions required."""
        if n == 0:  # to avoid division by zero
            return 0
        return max(1, math.ceil((m / n) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash value for the item using a specific seed."""
        hash_result = int(hashlib.sha256(f"{seed}{item}".encode()).hexdigest(), 16)
        return hash_result % self.num_bits

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for seed in self.seeds:
            index = self._hash(item, seed)
            self.bit_array[index] = True

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        for seed in self.seeds:
            index = self._hash(item, seed)
            if not self.bit_array[index]:
                return False
        return True

import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation using a dynamic array to simulate a bit array 
    and multiple hash functions generated from a simple hashing technique.
    This design supports quick membership testing while minimizing false positives.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.size = self._calculate_bit_array_size(expected_items, false_positive_rate)
        self.hash_count = self._calculate_hash_functions(self.size, expected_items)
        self.bit_array = [0] * (self.size // 32)  # Using int array (each int has 32 bits)

    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return int(-(n * math.log(p)) / (math.log(2) ** 2))

    def _calculate_hash_functions(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((m / n) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash for the item with a seed."""
        hash_object = hashlib.sha256((str(seed) + item).encode()).hexdigest()
        return int(hash_object, 16) % self.size

    def _set_bit(self, index: int) -> None:
        """Set the bit at the given index in the bit array."""
        self.bit_array[index // 32] |= (1 << (index % 32))

    def _get_bit(self, index: int) -> int:
        """Get the bit at the given index in the bit array."""
        return (self.bit_array[index // 32] >> (index % 32)) & 1

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            self._set_bit(index)

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            if self._get_bit(index) == 0:
                return False
        return True
